def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    opp_d = 0
    my_d = 0
    for i in range(n):
        mine, opp = history[i]
        if opp == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if mine == 'D':
            my_d += 1

    # Endgame: no future retaliation, so exploit anyone who won't punish immediately.
    rounds_left = 100 - n
    if rounds_left <= 1:
        last_opp = history[-1][1]
        if opp_d <= max(2, n // 20):
            return 'D'
        if last_opp == 'C':
            return 'D'
        return 'D' if opp_c > opp_d else 'C'

    # Pure / near-pure cooperators: farm them late, otherwise keep trust.
    if opp_d <= max(1, n // 20):
        if n >= 80:
            return 'D' if rng.random() < 0.9 else 'C'
        if n >= 55:
            return 'D' if rng.random() < 0.35 else 'C'
        if n >= 25 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Heavy defectors: protect ourselves, probe rarely to restart cooperation.
    if opp_d >= opp_c + 3 or (n >= 6 and opp_c == 0):
        last_opp = history[-1][1]
        if last_opp == 'C' and rng.random() < 0.5:
            return 'C'
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Look at recent window to classify behavior.
    w = min(8, n)
    start = n - w
    rec_opp_d = 0
    rec_opp_c = 0
    rec_my_d = 0
    rec_my_c = 0
    cc = 0
    dc = 0
    for i in range(start, n):
        mine, opp = history[i]
        if opp == 'D':
            rec_opp_d += 1
        else:
            rec_opp_c += 1
        if mine == 'D':
            rec_my_d += 1
        else:
            rec_my_c += 1

    # Count my successful exploitations recently.
    for i in range(start, n):
        mine, opp = history[i]
        if mine == 'D' and opp == 'C':
            dc += 1
        if mine == 'C' and opp == 'C':
            cc += 1

    last_me, last_opp = history[-1]

    # If opponent has been very cooperative recently, cooperate, but exploit late.
    if rec_opp_d <= 1 and rec_opp_c >= w - 1:
        if n >= 88 and rng.random() < 0.55:
            return 'D'
        return 'C'

    # Mutual defection spiral: try to break out occasionally.
    if last_opp == 'D' and last_me == 'D':
        if rec_opp_d >= 4:
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent defected, we cooperated: retaliate, sometimes forgive if rare.
    if last_opp == 'D':
        if rec_opp_d <= 1 and opp_d <= max(2, n // 6):
            if rng.random() < 0.35:
                return 'C'
        if dc >= 1 and rec_opp_c >= 2 and rng.random() < 0.3:
            return 'C'
        return 'D'

    # Last action was opponent C.
    # Exploit persistent cooperation with occasional defections.
    if dc >= 2 and rec_opp_c >= 3 and rng.random() < 0.25:
        return 'D'
    # Late-game exploitation against a tolerant opponent.
    if n >= 85 and rec_opp_d <= 1 and rng.random() < 0.25:
        return 'D'
    return 'C'
